def _load_from_file(base_dir, code):
    """Try to load override from lang/lang_{code}.json next to the exe.
    Returns {} if not found — embedded data will be used instead."""
    path = os.path.join(base_dir, "lang", f"lang_{code}.json")
    try:
        with open(path, "r", encoding="utf-8") as f:
            return json.load(f)
    except Exception:
        return {}


def _get_data(base_dir, code):
    """Return language data: file override if present, else embedded."""
    file_data = _load_from_file(base_dir, code)
    if file_data:
        return file_data
    return _EMBEDDED.get(code, {})


def _resolve(data, key):
    """Navigate a dot-separated key through nested dicts."""
    parts = key.split(".")
    node = data
    for part in parts:
        if isinstance(node, dict):
            node = node.get(part)
        else:
            return None
    return node if isinstance(node, str) else None


def t(key, **kwargs):
    """Get translated string. Falls back to English, then the key itself."""
    val = _resolve(_current_data, key)
    if val is None:
        val = _resolve(_fallback_data, key)
    if val is None:
        val = key
    if kwargs:
        try:
            val = val.format(**kwargs)
        except (KeyError, ValueError):
            pass
    return val


def init_lang(base_dir, code="en"):
    """Load the requested language. Call once at startup."""
    global _current_data, _fallback_data, _current_code
    _fallback_data = _get_data(base_dir, "en")
    if code == "en" or code not in LANG_CODES:
        _current_data = _fallback_data
        _current_code = "en"
    else:
        _current_data = _get_data(base_dir, code)
        _current_code = code
    if not _current_data:
        _current_data = _fallback_data
        _current_code = "en"


def set_lang(base_dir, code):
    """Switch active language at runtime."""
    init_lang(base_dir, code)


def get_lang():
    """Return current language code."""
    return _current_code
